#[allow(dead_code)]
pub fn json_newline(out: &mut String, depth: usize) {
    out.push('\n');
    for _ in 0..depth {
        out.push_str("  ");
    }
}

/// Escape one string as a JSON string (docs/SPEC-TABLES.md §16.2): the control
/// characters JSON spells, the quote and the backslash; every other code point
/// rides raw, so multibyte text stays byte for byte.
#[allow(dead_code)]
pub fn json_escape(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{0008}' => out.push_str("\\b"),
            '\u{000c}' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                out.push_str("\\u00");
                let h = format!("{:02x}", c as u32);
                out.push_str(&h);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

/// Clamp a string to n bytes at a code point boundary (docs/SPEC-TABLES.md
/// §16.2): longer than n is clamped, counted, never cut through a multibyte
/// character.
#[allow(dead_code)]
pub fn json_clamp(s: String, n: usize, clamped: &mut u64) -> String {
    if s.len() <= n {
        return s;
    }
    let mut end = n;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    *clamped += 1;
    s[..end].to_string()
}

/// A JSON string as wstring(N) code units (docs/SPEC-TABLES.md §16.2's wstring
/// row): transcoded at the boundary, and clamped at N CODE UNITS with a pair
/// never split; once a character does not fit nothing after it is kept, and
/// the clamp counts once (the oracle's tabletext scanWString).
#[allow(dead_code)]
pub fn json_wide_clamp(s: &str, n: usize, clamped: &mut u64) -> Vec<u16> {
    let mut out: Vec<u16> = Vec::new();
    let mut buf = [0u16; 2];
    for c in s.chars() {
        let units = c.encode_utf16(&mut buf);
        if out.len() + units.len() > n {
            *clamped += 1;
            break;
        }
        out.extend_from_slice(units);
    }
    out
}

pub const JSON_B64: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/// Bytes as a base64 JSON string (docs/SPEC-TABLES.md §16.2): the standard
/// alphabet, PADDED on write.
#[allow(dead_code)]
pub fn json_b64(bytes: &[u8], out: &mut String) {
    out.push('"');
    for chunk in bytes.chunks(3) {
        let triple = (chunk[0] as u32) << 16
            | (chunk.get(1).copied().unwrap_or(0) as u32) << 8
            | chunk.get(2).copied().unwrap_or(0) as u32;
        out.push(JSON_B64[(triple >> 18 & 0x3f) as usize] as char);
        out.push(JSON_B64[(triple >> 12 & 0x3f) as usize] as char);
        if chunk.len() > 1 { out.push(JSON_B64[(triple >> 6 & 0x3f) as usize] as char); } else { out.push('='); }
        if chunk.len() > 2 { out.push(JSON_B64[(triple & 0x3f) as usize] as char); } else { out.push('='); }
    }
    out.push('"');
}

/// Base64 back to bytes (docs/SPEC-TABLES.md §16.2): padded and unpadded both
/// read; anything else is None, which the caller counts kind_mismatch.
#[allow(dead_code)]
pub fn json_unb64(s: &str) -> Option<Vec<u8>> {
    let b = s.as_bytes();
    let mut end = b.len();
    while end > 0 && b[end - 1] == b'=' {
        end -= 1;
    }
    if b.len() - end > 2 || (b.len() != end && !b.len().is_multiple_of(4)) || end % 4 == 1 {
        return None;
    }
    let mut out = Vec::with_capacity(end * 3 / 4);
    let mut acc = 0u32;
    let mut bits = 0u32;
    for &c in &b[..end] {
        let v = match c {
            b'A'..=b'Z' => c - b'A',
            b'a'..=b'z' => c - b'a' + 26,
            b'0'..=b'9' => c - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            _ => return None,
        };
        acc = acc << 6 | v as u32;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((acc >> bits & 0xff) as u8);
        }
    }
    Some(out)
}

/// C's %.*g for a finite double, as the reference spells it
/// (internal/tabletext/write.go formatG): the exponent form when the decimal
/// exponent is below -4 or at least the precision, the plain form otherwise,
/// trailing zeros and a trailing point removed, an exponent of two digits.
#[allow(dead_code)]
pub fn json_format_g(v: f64, prec: usize) -> String {
    let trim = |s: &str| -> String {
        if !s.contains('.') {
            return s.to_string();
        }
        let t = s.trim_end_matches('0');
        t.trim_end_matches('.').to_string()
    };
    let sci = format!("{:.*e}", prec - 1, v);
    let (mant, exp) = sci.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    if exp < -4 || exp >= prec as i32 {
        let sign = if exp < 0 { '-' } else { '+' };
        return format!("{}e{}{:02}", trim(mant), sign, exp.abs());
    }
    trim(&format!("{:.*}", (prec as i32 - 1 - exp) as usize, v))
}

/// A FIXED value's text (docs/SPEC-TABLES.md §16.2): WHOLE UNITS, the shortest
/// EXACT decimal with at least one fractional digit (`1.0`, `-0.25`),
/// spelled from the raw integer at F fractional bits with no float between.
/// A signed raw value arrives sign-extended into the u128.
#[allow(dead_code)]
pub fn json_fixed(out: &mut String, raw: u128, signed: bool, frac: u32) {
    let mut m = raw;
    if signed && (raw as i128) < 0 {
        out.push('-');
        m = raw.wrapping_neg();
    }
    let whole = m.checked_shr(frac).unwrap_or(0);
    out.push_str(&whole.to_string());
    out.push('.');
    let mask = if frac >= 128 { u128::MAX } else { (1u128 << frac) - 1 };
    let mut f = m & mask;
    if f == 0 {
        out.push('0');
        return;
    }
    while f != 0 {
        // f × 10 across 132 bits: the digit is what rises past bit F
        let lo = (f as u64 as u128) * 10;
        let hi = (f >> 64) * 10 + (lo >> 64);
        let low = (hi << 64) | (lo & 0xffff_ffff_ffff_ffff);
        let carry = hi >> 64;
        let digit = if frac >= 128 { carry } else { (low >> frac) | (carry << (128 - frac)) };
        out.push((b'0' + digit as u8) as char);
        f = low & mask;
    }
}

/// A float at the SHORTEST precision that reads back as the same value at the
/// field's own width (docs/SPEC-TABLES.md §16.2), exactly as the reference
/// writes it. A non-finite value has no JSON spelling; the writer marks it.
#[allow(dead_code)]
pub fn json_float(v: f64, single: bool, w: &mut Jw) {
    if !v.is_finite() {
        w.refused = true;
        w.out.push_str("null");
        return;
    }
    let (low, high) = if single { (6, 9) } else { (15, 17) };
    let mut digits = low;
    loop {
        let text = json_format_g(v, digits);
        if digits >= high {
            w.out.push_str(&text);
            return;
        }
        if let Ok(back) = text.parse::<f64>() {
            let same = if single { (back as f32) as f64 == v } else { back == v };
            if same {
                w.out.push_str(&text);
                return;
            }
        }
        digits += 1;
    }
}

/// The text writer's state (docs/SPEC-TABLES.md §16.7): the text, how many slots
/// name each node (the first pass), the label each node named more than once
/// took (the second pass, from 1 in first-write order), and whether the graph
/// is past what the form can spell — the depth cap, or a value with no JSON
/// spelling (§16.3).
#[allow(dead_code)]
pub struct Jw {
    pub out: String,
    pub counts: HashMap<usize, u32>,
    pub labels: HashMap<usize, u64>,
    pub next: u64,
    pub refused: bool,
}

/// The DEPTH CAP the text form carries (docs/SPEC-TABLES.md §16.2, §16.7): a
/// chain nests as deep as it is long, and the writer refuses a graph past the
/// reader's cap rather than write a text the reader would refuse.
#[allow(dead_code)]
pub const JSON_DEPTH_CAP: usize = 128;

/// A label the reader has met (docs/SPEC-TABLES.md §16.7): Open while its
/// definition's object is still being read, then the node it defined — or
/// Dropped, a definition inside a value the walk skipped (past a bound, under
/// an unknown key). A dropped definition KEEPS its label and its reference
/// reads null, the wire's rule for an unnameable node (§3.1).
#[allow(dead_code)]
pub enum JsonLabel {
    Open,
    Node(Rc<dyn Any>),
    Dropped,
}

/// The tolerant JSON cursor (docs/SPEC-TABLES.md §16.2): it skips whitespace,
/// reads a string, a null and a number token, and skips a whole value it
/// cannot place. Its counters fold into the caller's report.
#[allow(dead_code)]
pub struct Jr<'a> {
    pub b: &'a [u8],
    pub p: usize,
    pub depth: usize,
    pub unknown: u64,
    pub kind_mismatch: u64,
    pub clamped: u64,
    pub duplicate: u64,
    pub malformed: bool,
    /// set when a string decoded the U+0000 escape; read_text refuses it (§16.3)
    pub zero: bool,
    pub labels: HashMap<u64, JsonLabel>,
}

#[allow(dead_code)]
impl<'a> Jr<'a> {
    pub fn new(b: &'a [u8]) -> Jr<'a> {
        Jr { b, p: 0, depth: 0, unknown: 0, kind_mismatch: 0, clamped: 0, duplicate: 0, malformed: false, zero: false, labels: HashMap::new() }
    }
    pub fn space(&mut self) {
        while self.p < self.b.len() {
            match self.b[self.p] {
                b' ' | b'\t' | b'\n' | b'\r' => self.p += 1,
                b'/' if self.p + 1 < self.b.len() && self.b[self.p + 1] == b'/' => {
                    self.p += 2;
                    while self.p < self.b.len() && self.b[self.p] != b'\n' {
                        self.p += 1;
                    }
                }
                b'/' if self.p + 1 < self.b.len() && self.b[self.p + 1] == b'*' => {
                    self.p += 2;
                    let mut closed = false;
                    while self.p + 1 < self.b.len() {
                        if self.b[self.p] == b'*' && self.b[self.p + 1] == b'/' {
                            self.p += 2;
                            closed = true;
                            break;
                        }
                        self.p += 1;
                    }
                    if !closed {
                        self.malformed = true;
                        self.p = self.b.len();
                        return;
                    }
                }
                b'/' => {
                    self.malformed = true;
                    return;
                }
                _ => break,
            }
        }
    }
    pub fn peek(&mut self) -> u8 {
        self.space();
        if self.p < self.b.len() {
            self.b[self.p]
        } else {
            0
        }
    }
    pub fn hex4(&mut self) -> i32 {
        if self.p + 4 > self.b.len() {
            return -1;
        }
        let mut v = 0i32;
        for i in 0..4 {
            let c = self.b[self.p + i];
            let d = match c {
                b'0'..=b'9' => (c - b'0') as i32,
                b'a'..=b'f' => (c - b'a' + 10) as i32,
                b'A'..=b'F' => (c - b'A' + 10) as i32,
                _ => return -1,
            };
            v = v * 16 + d;
        }
        self.p += 4;
        v
    }
    pub fn read_string(&mut self) -> Option<String> {
        self.space();
        if self.p >= self.b.len() || self.b[self.p] != b'"' {
            self.malformed = true;
            return None;
        }
        self.p += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            if self.p >= self.b.len() {
                self.malformed = true;
                return None;
            }
            let c = self.b[self.p];
            if c == b'"' {
                self.p += 1;
                break;
            }
            if c < 0x20 {
                self.malformed = true;
                return None;
            }
            if c == b'\\' {
                self.p += 1;
                if self.p >= self.b.len() {
                    self.malformed = true;
                    return None;
                }
                let e = self.b[self.p];
                self.p += 1;
                match e {
                    b'"' => out.push(b'"'),
                    b'\\' => out.push(b'\\'),
                    b'/' => out.push(b'/'),
                    b'b' => out.push(0x08),
                    b'f' => out.push(0x0c),
                    b'n' => out.push(b'\n'),
                    b'r' => out.push(b'\r'),
                    b't' => out.push(b'\t'),
                    b'u' => {
                        let v = self.hex4();
                        if v < 0 {
                            self.malformed = true;
                            return None;
                        }
                        let mut cp = v as u32;
                        if (0xd800..0xdc00).contains(&cp)
                            && self.p + 6 <= self.b.len()
                            && self.b[self.p] == b'\\'
                            && self.b[self.p + 1] == b'u'
                        {
                            let mark = self.p;
                            self.p += 2;
                            let lo = self.hex4();
                            if (0xdc00..0xe000).contains(&lo) {
                                cp = 0x10000 + ((cp - 0xd800) << 10) + (lo as u32 - 0xdc00);
                            } else {
                                // a lone lead surrogate rides as itself, and the
                                // escape after it is read on its own
                                self.p = mark;
                            }
                        }
                        self.zero |= cp == 0;
                        let ch = char::from_u32(cp).unwrap_or('\u{fffd}');
                        let mut buf = [0u8; 4];
                        out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                    }
                    _ => {
                        self.malformed = true;
                        return None;
                    }
                }
            } else {
                out.push(c);
                self.p += 1;
            }
        }
        // §16.3: bytes that are not well-formed UTF-8 spell no code point,
        // so the read refuses them by name (string_not_utf8) at every string
        // site, before any clamp, and never replaces them with U+FFFD
        match String::from_utf8(out) {
            Ok(s) => Some(s),
            Err(_) => {
                self.malformed = true;
                None
            }
        }
    }
    /// read_text reads a string the read PLACES in text storage: a U+0000 in
    /// it refuses the read (text_holds_zero, docs/SPEC-TABLES.md §16.3), while
    /// a string the read only compares or skips goes through read_string.
    pub fn read_text(&mut self) -> Option<String> {
        self.zero = false;
        let s = self.read_string()?;
        if self.zero {
            self.malformed = true;
            return None;
        }
        Some(s)
    }
    pub fn read_null(&mut self) -> bool {
        self.space();
        if self.p + 4 <= self.b.len() && &self.b[self.p..self.p + 4] == b"null" {
            self.p += 4;
            true
        } else {
            self.malformed = true;
            false
        }
    }
    /// One number token, by RFC 8259's grammar (docs/SPEC-TABLES.md §16.2): a
    /// token that is not a JSON number at all is malformed.
    pub fn number_token(&mut self) -> Option<String> {
        self.space();
        let b = self.b;
        let s = self.p;
        let mut p = s;
        let digit = |p: usize| p < b.len() && b[p].is_ascii_digit();
        if p < b.len() && b[p] == b'-' {
            p += 1;
        }
        if !digit(p) {
            self.malformed = true;
            return None;
        }
        if b[p] == b'0' {
            p += 1;
        } else {
            while digit(p) {
                p += 1;
            }
        }
        if p < b.len() && b[p] == b'.' {
            p += 1;
            if !digit(p) {
                self.malformed = true;
                return None;
            }
            while digit(p) {
                p += 1;
            }
        }
        if p < b.len() && (b[p] == b'e' || b[p] == b'E') {
            p += 1;
            if p < b.len() && (b[p] == b'+' || b[p] == b'-') {
                p += 1;
            }
            if !digit(p) {
                self.malformed = true;
                return None;
            }
            while digit(p) {
                p += 1;
            }
        }
        if p < b.len() && !matches!(b[p], b' ' | b'\t' | b'\n' | b'\r' | b',' | b'}' | b']' | b'/') {
            self.malformed = true;
            return None;
        }
        self.p = p;
        Some(String::from_utf8_lossy(&b[s..p]).into_owned())
    }
    /// An integer field's value (docs/SPEC-TABLES.md §16.2): any token whose
    /// VALUE is integral, saturating past what 64 bits hold; a fractional one
    /// is kind_mismatch, and a value of another JSON type is kind_mismatch,
    /// skipped.
    pub fn read_int(&mut self) -> Option<i128> {
        let c = self.peek();
        if matches!(c, b'{' | b'[' | b'"' | b't' | b'f' | b'n') {
            self.kind_mismatch += 1;
            self.skip_value();
            return None;
        }
        let t = self.number_token()?;
        if !t.contains(['.', 'e', 'E']) {
            let neg = t.starts_with('-');
            let digits = t.strip_prefix('-').unwrap_or(&t);
            let mut mag: u64 = 0;
            for b in digits.bytes() {
                let d = (b - b'0') as u64;
                if mag > (u64::MAX - d) / 10 {
                    mag = u64::MAX;
                    self.clamped += 1;
                    break;
                }
                mag = mag * 10 + d;
            }
            if mag == 0 {
                return Some(0);
            }
            return Some(if neg { -(mag as i128) } else { mag as i128 });
        }
        let f: f64 = t.parse().ok()?;
        if !f.is_finite() || f.fract() != 0.0 {
            self.kind_mismatch += 1;
            return None;
        }
        let neg = f.is_sign_negative();
        let whole = f.abs();
        let mag = if whole >= 18446744073709551616.0 {
            self.clamped += 1;
            u64::MAX
        } else {
            whole as u64
        };
        if mag == 0 {
            return Some(0);
        }
        Some(if neg { -(mag as i128) } else { mag as i128 })
    }
    /// A WIDE value (docs/SPEC-TABLES.md §16.2): a 128-bit integer (frac 0)
    /// or a fixed(I, F)'s raw integer, read EXACTLY from any number token whose
    /// value the Q I.F grid holds — `2`, `2.0` and `20e-1` are one value —
    /// with no binary float between, as two's complement in a u128. A digit
    /// the grid cannot hold is kind_mismatch, the wrong shape, never rounded;
    /// a magnitude past 128 bits saturates and counts clamped; a value of
    /// another JSON type is kind_mismatch, skipped. The caller clamps to the
    /// field's raw range.
    pub fn read_wide(&mut self, signed: bool, frac: u32) -> Option<u128> {
        let c = self.peek();
        if matches!(c, b'{' | b'[' | b'"' | b't' | b'f' | b'n') {
            self.kind_mismatch += 1;
            self.skip_value();
            return None;
        }
        let token = self.number_token()?;
        let t = token.as_bytes();
        let negative = t.first() == Some(&b'-');
        let mut i = usize::from(negative);
        let int_start = i;
        while i < t.len() && t[i].is_ascii_digit() {
            i += 1;
        }
        let int_len = i - int_start;
        let mut frac_start = i;
        let mut frac_len = 0;
        if i < t.len() && t[i] == b'.' {
            i += 1;
            frac_start = i;
            while i < t.len() && t[i].is_ascii_digit() {
                i += 1;
            }
            frac_len = i - frac_start;
        }
        let mut exp: i64 = 0;
        if i < t.len() && (t[i] == b'e' || t[i] == b'E') {
            i += 1;
            let mut eneg = false;
            if i < t.len() && (t[i] == b'-' || t[i] == b'+') {
                eneg = t[i] == b'-';
                i += 1;
            }
            while i < t.len() && t[i].is_ascii_digit() {
                if exp < 100000 {
                    exp = exp * 10 + i64::from(t[i] - b'0');
                }
                i += 1;
            }
            if eneg {
                exp = -exp;
            }
        }
        let digit = |k: usize| if k < int_len { t[int_start + k] } else { t[frac_start + k - int_len] };
        let (mut start, mut end) = (0usize, int_len + frac_len);
        let mut point = int_len as i64 + exp;
        while start < end && digit(start) == b'0' {
            start += 1;
            point -= 1;
        }
        while end > start && digit(end - 1) == b'0' {
            end -= 1;
        }
        let signed_max = i128::MAX as u128;
        let signed_min = 1u128 << 127;
        let mut raw = 0u128;
        let mut saturated = false;
        if start == end {
            // zero, in any spelling, -0 included
        } else if point > 40 {
            saturated = true;
            raw = match (negative, signed) {
                (false, true) => signed_max,
                (false, false) => u128::MAX,
                (true, true) => signed_min,
                (true, false) => 0,
            };
        } else if point < -40 {
            self.kind_mismatch += 1;
            return None;
        } else {
            // the decimal fraction, at most 128 places: Q I.F holds I + F <= 128
            // bits, so a nonzero digit past the 128th place is inexact
            let mut fd = [0u8; 128];
            let mut n = point.min(0).unsigned_abs() as usize;
            let mut k = (point.max(0) as usize) + start;
            while k < end {
                if n >= 128 {
                    if digit(k) != b'0' {
                        self.kind_mismatch += 1;
                        return None;
                    }
                } else {
                    fd[n] = digit(k) - b'0';
                    n += 1;
                }
                k += 1;
            }
            let mut fraction = 0u128;
            for _ in 0..frac {
                let mut carry = 0u8;
                for d in fd[..n].iter_mut().rev() {
                    let x = *d * 2 + carry;
                    *d = x % 10;
                    carry = x / 10;
                }
                fraction = (fraction << 1) | u128::from(carry);
            }
            if fd[..n].iter().any(|&d| d != 0) {
                self.kind_mismatch += 1;
                return None;
            }
            let mut whole = 0u128;
            let mut k = start as i64;
            while k < start as i64 + point && !saturated {
                let d = if (k as usize) < end { u128::from(digit(k as usize) - b'0') } else { 0 };
                match whole.checked_mul(10).and_then(|w| w.checked_add(d)) {
                    Some(w) => whole = w,
                    None => saturated = true,
                }
                k += 1;
            }
            if !saturated && frac > 0 && whole.checked_shr(128 - frac).unwrap_or(0) != 0 {
                saturated = true;
            }
            if !saturated {
                raw = whole.checked_shl(frac).unwrap_or(0) | fraction;
            }
            if signed {
                if !saturated && !negative && raw >> 127 != 0 {
                    saturated = true;
                }
                if !saturated && negative && raw > signed_min {
                    saturated = true;
                }
                if saturated {
                    raw = if negative { signed_min } else { signed_max };
                } else if negative {
                    raw = raw.wrapping_neg();
                }
            } else {
                if saturated {
                    raw = u128::MAX;
                }
                if negative && raw != 0 {
                    raw = 0;
                    saturated = true;
                }
            }
        }
        if saturated {
            self.clamped += 1;
        }
        Some(raw)
    }
    /// A float field's value (docs/SPEC-TABLES.md §16.2).
    pub fn read_float(&mut self) -> Option<f64> {
        let c = self.peek();
        if matches!(c, b'{' | b'[' | b'"' | b't' | b'f' | b'n') {
            self.kind_mismatch += 1;
            self.skip_value();
            return None;
        }
        let t = self.number_token()?;
        t.parse::<f64>().ok()
    }
    /// A float32 field's value, converted once at single width (§16.2).
    pub fn read_f32(&mut self) -> Option<f32> {
        let c = self.peek();
        if matches!(c, b'{' | b'[' | b'"' | b't' | b'f' | b'n') {
            self.kind_mismatch += 1;
            self.skip_value();
            return None;
        }
        let t = self.number_token()?;
        t.parse::<f32>().ok()
    }
    /// A label (docs/SPEC-TABLES.md §16.7): a positive integer spelled as one —
    /// digits, no sign, no fraction, no exponent, no leading zero.
    pub fn read_label(&mut self) -> Option<u64> {
        self.space();
        let b = self.b;
        let s = self.p;
        let mut p = s;
        if p >= b.len() || !(b'1'..=b'9').contains(&b[p]) {
            return None;
        }
        while p < b.len() && b[p].is_ascii_digit() {
            p += 1;
        }
        if p < b.len() && !matches!(b[p], b' ' | b'\t' | b'\n' | b'\r' | b',' | b'}' | b'/') {
            return None;
        }
        let v = std::str::from_utf8(&b[s..p]).ok()?.parse::<u64>().ok()?;
        self.p = p;
        Some(v)
    }
    /// A REFERENCE (docs/SPEC-TABLES.md §16.7): a label the text has defined,
    /// alone, resolves against the labeled node's TABLE — another table is
    /// kind_mismatch, the pointer null; a label not yet defined, or one whose
    /// definition is still open, is malformed.
    pub fn refer<T: 'static>(&mut self, label: u64) -> Option<Rc<T>> {
        match self.labels.get(&label) {
            Some(JsonLabel::Node(n)) => match n.clone().downcast::<T>() {
                Ok(t) => Some(t),
                Err(_) => {
                    self.kind_mismatch += 1;
                    None
                }
            },
            // a definition the walk dropped reads null, and counts nothing
            // past what dropping it already counted (§16.7)
            Some(JsonLabel::Dropped) => None,
            _ => {
                self.malformed = true;
                None
            }
        }
    }
    pub fn skip_value(&mut self) {
        self.space();
        if self.p >= self.b.len() {
            self.malformed = true;
            return;
        }
        match self.b[self.p] {
            b'"' => {
                let _ = self.read_string();
            }
            b'{' => {
                if self.depth > JSON_DEPTH_CAP {
                    self.malformed = true;
                    return;
                }
                self.p += 1;
                self.depth += 1;
                loop {
                    self.space();
                    if self.p >= self.b.len() {
                        self.malformed = true;
                        self.depth -= 1;
                        return;
                    }
                    if self.b[self.p] == b'}' {
                        self.p += 1;
                        self.depth -= 1;
                        return;
                    }
                    let key = self.read_string();
                    if self.malformed {
                        self.depth -= 1;
                        return;
                    }
                    self.space();
                    if self.p < self.b.len() && self.b[self.p] == b':' {
                        self.p += 1;
                    }
                    // A DEFINITION INSIDE A SKIPPED VALUE (§16.7): an &node
                    // label followed by a field keeps its label as Dropped, so a
                    // reference to it reads null; an &node alone is a reference
                    // and defines nothing.
                    let mut labelled = false;
                    if key.as_deref() == Some("&node")
                        && let Some(label) = self.read_label()
                    {
                        labelled = true;
                        self.space();
                        if self.p < self.b.len() && self.b[self.p] == b',' {
                            self.labels.entry(label).or_insert(JsonLabel::Dropped);
                        }
                    }
                    if !labelled {
                        self.skip_value();
                    }
                    if self.malformed {
                        self.depth -= 1;
                        return;
                    }
                    self.space();
                    if self.p < self.b.len() && self.b[self.p] == b',' {
                        self.p += 1;
                    }
                }
            }
            b'[' => {
                if self.depth > JSON_DEPTH_CAP {
                    self.malformed = true;
                    return;
                }
                self.p += 1;
                self.depth += 1;
                loop {
                    self.space();
                    if self.p >= self.b.len() {
                        self.malformed = true;
                        self.depth -= 1;
                        return;
                    }
                    if self.b[self.p] == b']' {
                        self.p += 1;
                        self.depth -= 1;
                        return;
                    }
                    self.skip_value();
                    if self.malformed {
                        self.depth -= 1;
                        return;
                    }
                    self.space();
                    if self.p < self.b.len() && self.b[self.p] == b',' {
                        self.p += 1;
                    }
                }
            }
            b't' => {
                if self.b[self.p..].starts_with(b"true") {
                    self.p += 4;
                } else {
                    self.malformed = true;
                }
            }
            b'f' => {
                if self.b[self.p..].starts_with(b"false") {
                    self.p += 5;
                } else {
                    self.malformed = true;
                }
            }
            b'n' => {
                let _ = self.read_null();
            }
            _ => {
                let _ = self.number_token();
            }
        }
    }
}

// ---- the COOK WRITE side's region writer (docs/SPEC-TABLES.md §6.3, §7) ----

/// One region being written: the DATA part, the byte order (1 little, 2 big),
/// the numbering it lays out and each node's region offset, by index - 1 (the
/// root is offset 0). A refusal clears ok and the cook writes nothing.
#[cfg(feature = "cook")]
pub struct TableRegionWriter<'a> {
    pub data: Vec<u8>,
    pub order: u64,
    pub align: i64,
    pub graph: &'a TableNodeGraph,
    pub offsets: Vec<i64>,
    pub ok: bool,
}

#[cfg(feature = "cook")]
fn table_region_up(v: i64, a: i64) -> i64 {
    (v + a - 1) / a * a
}

/// THE LAYOUT (internal/tablecook/region.go's Layout): the root at the base
/// (root_size is its record and its extent), then every node of the numbering
/// in index order at its own alignment — a table node its record and its
/// extent, a
/// blob at eight, its u32 length, four zero bytes, its bytes and a *string
/// blob's terminator — and the data part rounded to the region's alignment,
/// the greatest record alignment, never below eight.
#[cfg(feature = "cook")]
pub fn table_region_layout(
    g: &TableNodeGraph,
    root_size: i64,
    root_align: i64,
    layout: fn(u64) -> Option<(i64, i64)>,
    extent: fn(u64, &Rc<dyn Any>) -> i64,
    order: u64,
) -> Result<TableRegionWriter<'_>, String> {
    let mut align = root_align.max(8);
    let mut offset = root_size;
    let mut offsets = Vec::with_capacity(g.records.len() + 1);
    offsets.push(0);
    for rec in g.records.iter() {
        match rec {
            TableNodeRecord::Blob(type_id, blob) => {
                if blob.len() as u64 > u32::MAX as u64 {
                    return Err(String::from("invalid_value"));
                }
                offset = table_region_up(offset, 8);
                offsets.push(offset);
                offset += 8 + blob.len() as i64 + if *type_id == STRING_TYPE_ID { 1 } else { 0 };
            }
            TableNodeRecord::Table(type_id, node) => {
                let Some((size, a)) = layout(*type_id) else {
                    return Err(String::from("invalid_value"));
                };
                align = align.max(a);
                offset = table_region_up(offset, a);
                offsets.push(offset);
                // a NODE'S SIZE DEPENDS ON ITS VALUE where a list or a map
                // rides in its extent (§2.8, §2.9): the record, then the extent
                offset += size + extent(*type_id, node);
            }
        }
    }
    let bytes = table_region_up(offset, align);
    Ok(TableRegionWriter { data: vec![0u8; bytes as usize], order, align, graph: g, offsets, ok: true })
}

#[cfg(feature = "cook")]
impl TableRegionWriter<'_> {
    pub fn fail(&mut self) {
        self.ok = false;
    }

    /// One scalar of width bytes at a region offset, in the cook's byte order.
    pub fn put(&mut self, at: i64, value: u64, width: u32) {
        let at = at as usize;
        for i in 0..width as usize {
            let shift = if self.order == 2 { width as usize - 1 - i } else { i };
            self.data[at + i] = (value >> (shift * 8)) as u8;
        }
    }

    /// A float32 as its bit pattern; a NaN or an infinity refuses (§3.3).
    pub fn put_f32(&mut self, at: i64, value: f32) {
        if !value.is_finite() {
            self.ok = false;
            return;
        }
        self.put(at, value.to_bits() as u64, 4);
    }

    /// A float64 as its bit pattern; a NaN or an infinity refuses (§3.3).
    pub fn put_f64(&mut self, at: i64, value: f64) {
        if !value.is_finite() {
            self.ok = false;
            return;
        }
        self.put(at, value.to_bits(), 8);
    }

    /// A 128-bit integer: a big-endian region holds its high half first, as
    /// it holds a u64 with its high byte first (§7.2).
    pub fn put_wide(&mut self, at: i64, value: u128) {
        let bytes = if self.order == 2 { value.to_be_bytes() } else { value.to_le_bytes() };
        self.data[at as usize..at as usize + 16].copy_from_slice(&bytes);
    }

    /// string(N) or bytes(N): the used bytes, a zero tail, and the int32 used
    /// length at its own piece; a value over its declared bound refuses.
    pub fn put_text(&mut self, at: i64, bytes: &[u8], bound: usize, length_at: i64) {
        if bytes.len() > bound {
            self.ok = false;
            return;
        }
        self.data[at as usize..at as usize + bytes.len()].copy_from_slice(bytes);
        self.put(length_at, bytes.len() as u64, 4);
    }

    /// wstring(N): the used CODE UNITS, each a two-byte scalar in the cook's
    /// byte order, and the int32 used length in units (§7.2).
    pub fn put_units(&mut self, at: i64, units: &[u16], bound: usize, length_at: i64) {
        if units.len() > bound {
            self.ok = false;
            return;
        }
        for (i, u) in units.iter().enumerate() {
            self.put(at + 2 * i as i64, *u as u64, 2);
        }
        self.put(length_at, units.len() as u64, 4);
    }

    /// A reference slot to a table node: the SELF-RELATIVE delta from the
    /// slot's own address to the node's start, and zero for null (§6.3).
    pub fn ref_node<T>(&mut self, at: i64, node: &Option<Rc<T>>) {
        match node {
            None => self.put(at, 0, 8),
            Some(n) => {
                let index = self.graph.node_index(n) as usize;
                self.ref_index(at, index);
            }
        }
    }

    /// A reference slot to a blob node, by the blob's identity (§2.5).
    pub fn ref_blob(&mut self, at: i64, key: Option<usize>) {
        match key {
            None => self.put(at, 0, 8),
            Some(k) => {
                let index = self.graph.blob_index(k) as usize;
                self.ref_index(at, index);
            }
        }
    }

    fn ref_index(&mut self, at: i64, index: usize) {
        if index < 2 || index > self.offsets.len() {
            self.ok = false; // a node the numbering does not carry
            return;
        }
        let delta = self.offsets[index - 1] - at;
        if delta == 0 {
            self.ok = false;
            return;
        }
        self.put(at, delta as u64, 8);
    }

    /// A blob node: its u32 length in the cook's order, then its bytes; the
    /// pad word and a *string blob's terminator are the buffer's zeros.
    pub fn put_blob(&mut self, at: i64, blob: &[u8]) {
        self.put(at, blob.len() as u64, 4);
        let from = at as usize + 8;
        self.data[from..from + blob.len()].copy_from_slice(blob);
    }

    /// Frame the region (§7.1): the 64-byte header, the data part at
    /// align_up(64, alignment), and the node directory — each node's offset
    /// and type id — as the attribution part.
    pub fn finish(self, g: &TableNodeGraph, root_type: u64, build: u64) -> Result<Vec<u8>, String> {
        if !self.ok {
            return Err(String::from("invalid_value"));
        }
        let data_offset = table_region_up(64, self.align) as usize;
        let nodes = g.records.len() + 1;
        let total = data_offset + self.data.len() + nodes * 16;
        let mut out = TableRegionWriter { data: vec![0u8; total], order: self.order, align: self.align, graph: g, offsets: Vec::new(), ok: true };
        out.put(0, 0x4b4f4f434d484353, 8);
        out.put(8, build, 8);
        out.put(16, self.order, 8);
        out.put(24, self.data.len() as u64, 8);
        out.put(32, (nodes * 16) as u64, 8);
        out.put(40, self.align as u64, 8);
        out.data[data_offset..data_offset + self.data.len()].copy_from_slice(&self.data);
        let mut at = (data_offset + self.data.len()) as i64;
        for k in 0..nodes {
            let id = if k == 0 {
                root_type
            } else {
                match &g.records[k - 1] {
                    TableNodeRecord::Blob(type_id, _) => *type_id,
                    TableNodeRecord::Table(type_id, _) => *type_id,
                }
            };
            out.put(at, self.offsets[k] as u64, 8);
            out.put(at + 8, id, 8);
            at += 16;
        }
        Ok(out.data)
    }
}

/// One node's extent being carved (docs/SPEC-TABLES.md §2.8, §2.9): where the
/// extent begins in the region and the running offset inside it.
#[cfg(feature = "cook")]
pub struct TableCarve {
    pub extent_at: i64,
    pub at: i64,
}

#[cfg(feature = "cook")]
impl TableCarve {
    /// Reserve one container's whole array, count x size at align, and answer
    /// where it starts inside the extent.
    pub fn place(&mut self, count: usize, size: i64, align: i64) -> i64 {
        self.at = (self.at + align - 1) / align * align;
        let start = self.at;
        self.at += count as i64 * size;
        start
    }
}

#[cfg(feature = "cook")]
impl TableRegionWriter<'_> {
    /// A container's sixteen-byte slot: the SELF-RELATIVE delta from the slot
    /// to its array and the int32 count, or the null reference and zero for
    /// an empty one (§2.8, §2.9).
    pub fn put_slot(&mut self, at: i64, array: i64, count: usize) {
        if count == 0 {
            self.put(at, 0, 8);
            self.put(at + 8, 0, 4);
            return;
        }
        if count > i32::MAX as usize {
            self.ok = false;
            return;
        }
        self.put(at, (array - at) as u64, 8);
        self.put(at + 8, count as u64, 4);
    }
}
